import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.DxEvSMU4.js";const k=JSON.parse('{"title":"風險自評","description":"","frontmatter":{},"headers":[],"relativePath":"decide/risk-checklist.md","filePath":"decide/risk-checklist.md","lastUpdated":1793014002000}'),o={name:"decide/risk-checklist.md"};function i(n,t,l,s,h,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="風險自評" tabindex="-1">風險自評 <a class="header-anchor" href="#風險自評" aria-label="Permalink to &quot;風險自評&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: 決策參考</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li></ul></div><p><strong>結論</strong>: 十個問題中, 答「是」越多, 維運前提越穩. 建議門檻為整理者推論 (信心: 低), 用意是找出缺口, 不是評分.</p><h2 id="十個問題" tabindex="-1">十個問題 <a class="header-anchor" href="#十個問題" aria-label="Permalink to &quot;十個問題&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>問題</th><th>對應章節</th></tr></thead><tbody><tr><td>1</td><td>有具名的人, 每週檢查一次安全公告?</td><td><a href="/lanai-handbook/ops/advisories">O3</a></td></tr><tr><td>2</td><td>所有服務只綁本機或私有網路, 包含容器發布的連接埠?</td><td><a href="/lanai-handbook/build/overview">M2</a></td></tr><tr><td>3</td><td>每個元件的版本已鎖定並有紀錄, 沒有使用 latest 之類的浮動標籤?</td><td><a href="/lanai-handbook/ops/versioning">O2</a></td></tr><tr><td>4</td><td>每週備份資料卷, 且做過一次還原演練?</td><td><a href="/lanai-handbook/ops/backup">O1</a></td></tr><tr><td>5</td><td>所有金鑰的存放位置已列出, 並確認能在短時間內輪替?</td><td><a href="/lanai-handbook/ops/advisories">O3.3 節</a></td></tr><tr><td>6</td><td>每位使用者有個別帳號, 且已關閉公開註冊?</td><td><a href="/lanai-handbook/know/k6-security">K6.1 節</a></td></tr><tr><td>7</td><td>模型檔來自可追溯的官方來源, 並優先使用 safetensors 或 GGUF?</td><td><a href="/lanai-handbook/build/m1-inference">M1.5 節</a></td></tr><tr><td>8</td><td>檢索用的文件來源只限可信資料夾?</td><td><a href="/lanai-handbook/build/m4-retrieval">M4</a></td></tr><tr><td>9</td><td>若有代理, MCP 或程式碼執行: 已放進沙箱, 且寫入與刪除需人工確認?</td><td><a href="/lanai-handbook/know/k6-security">K6.3 節</a>, <a href="/lanai-handbook/build/m7-tools-sandbox">M7</a></td></tr><tr><td>10</td><td>保留上一版映像與模型, 升級失敗時可回退?</td><td><a href="/lanai-handbook/ops/versioning">O2</a></td></tr></tbody></table><h2 id="結果判讀" tabindex="-1">結果判讀 <a class="header-anchor" href="#結果判讀" aria-label="Permalink to &quot;結果判讀&quot;">​</a></h2><table tabindex="0"><thead><tr><th>答「是」的數量</th><th>建議</th></tr></thead><tbody><tr><td>8 至 10</td><td>可進入 PoC 或小範圍試用; 其餘缺口列入待辦</td></tr><tr><td>5 至 7</td><td>先補齊缺口, 再開放給多人</td></tr><tr><td>4 以下</td><td>僅限單人本機使用, 不對外開放</td></tr></tbody></table><p>答「否」的問題, 在對應章節都有可行做法. 優先補第 2, 3, 4 題, 因為這三項成本低, 且涵蓋 2026 年已知的主要事件起點 (見 <a href="/lanai-handbook/ops/advisories">O3</a>).</p><p>本自評不涉及法規遵循. 該部分請由法務或資安負責人另行檢視.</p>',9)])])}const p=a(o,[["render",i]]);export{k as __pageData,p as default};
